from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Lossless bounded optimizer for character-prefix reuse in serialized rows."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe and basic shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Serialize a scalar exactly as the evaluator does for scoring."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute LCP length using logarithmically many C-level slice comparisons."""
        high = min(len(left), len(right))
        low = 0
        while low < high:
            mid = (low + high + 1) // 2
            if left[:mid] == right[:mid]:
                low = mid
            else:
                high = mid - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Return exact ideal character-Trie reuse for a multiset of row strings."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        return sum(
            cls._lcp(ordered[i - 1], ordered[i])
            for i in range(1, len(ordered))
        )

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize each row using its row-specific source-column permutation."""
        return [
            "".join(cells[row, col] for col in orders[row])
            for row in range(cells.shape[0])
        ]

    def _global_order(self, cells, mode: int) -> List[int]:
        """Rank columns by length-weighted pair repetition with deterministic ties."""
        n, m = cells.shape
        ranked = []

        for col in range(m):
            counts = {}
            total_length = 0
            for value in cells[:, col]:
                counts[value] = counts.get(value, 0) + 1
                total_length += len(value)

            weighted = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            repetition = sum(
                count * (count - 1)
                for count in counts.values()
            )

            if mode == 0:
                score = weighted
            else:
                score = weighted + repetition * max(
                    1, total_length // max(1, n)
                )

            ranked.append((score, col))

        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [col for _, col in ranked]

    def _pair_orders(self, cells, base_order) -> List[List[int]]:
        """Build row-specific orders from bounded greedy cross-row prefix matching."""
        n, m = cells.shape
        orders = [list(base_order) for _ in range(n)]

        if n < 2 or m < 2:
            return orders

        # Select the most repetitive columns as inexpensive anchor sources.
        repetitive = []
        for col in range(m):
            counts = {}
            for value in cells[:, col]:
                counts[value] = counts.get(value, 0) + 1

            score = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            repetitive.append((score, col))

        repetitive.sort(key=lambda item: (-item[0], item[1]))
        anchor_cols = [col for _, col in repetitive[:8]]

        # Inverted prefix buckets provide at most a small partner neighborhood.
        buckets = {}
        for row in range(n):
            for col in anchor_cols:
                value = cells[row, col]
                for width in (1, 2, 4):
                    key = (width, value[:width])
                    bucket = buckets.setdefault(key, [])
                    if len(bucket) < 12:
                        bucket.append(row)

        proposals = []
        for row in range(n):
            partners = set()
            for col in anchor_cols:
                value = cells[row, col]
                for width in (1, 2, 4):
                    for other in buckets.get((width, value[:width]), ()):
                        if other != row:
                            partners.add(other)

            # Deterministic cap on partner exploration.
            partner_list = sorted(partners)[:8]
            local = []

            for other in partner_list:
                best = None
                tested = 0

                for left_col in anchor_cols:
                    for right_col in anchor_cols:
                        if left_col == right_col:
                            continue

                        weight = self._lcp(
                            cells[row, left_col],
                            cells[other, right_col],
                        )
                        tested += 1

                        candidate = (
                            weight,
                            -left_col,
                            -right_col,
                            left_col,
                            right_col,
                        )
                        if best is None or candidate > best:
                            best = candidate

                        if tested >= 32:
                            break
                    if tested >= 32:
                        break

                if best is not None and best[0] > 0:
                    local.append((best[0], row, other, best[3], best[4]))

            if local:
                # Keep only the strongest proposal for this row.
                local.sort(key=lambda item: (-item[0], item[1], item[2]))
                proposals.append(local[0])

        # Greedily accept globally nonoverlapping positive-weight pairs.
        proposals.sort(key=lambda item: (-item[0], item[1], item[2]))
        used = set()

        for weight, left_row, right_row, left_col, right_col in proposals:
            if left_row in used or right_row in used:
                continue

            used.add(left_row)
            used.add(right_row)

            left_tail = [col for col in base_order if col != left_col]
            right_tail = [col for col in base_order if col != right_col]

            orders[left_row] = [left_col] + left_tail
            orders[right_row] = [right_col] + right_tail

        return orders

    def _candidate(self, cells, orders):
        """Serialize and exactly score one candidate, returning deterministic row order."""
        strings = self._make_strings(cells, orders)
        score = self._trie_score(strings)
        row_order = sorted(
            range(len(strings)),
            key=lambda row: (strings[row], row),
        )
        return score, strings, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate two global orders and one greedy cross-row pairing candidate."""
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)

        for row in range(n):
            for col in range(m):
                cells[row, col] = self._cell_text(raw[row, col])

        global_a = self._global_order(cells, 0)
        global_b = self._global_order(cells, 1)
        paired = self._pair_orders(cells, global_a)

        candidates = [
            [global_a[:] for _ in range(n)],
            [global_b[:] for _ in range(n)],
            paired,
        ]

        best = None
        for orders in candidates:
            score, strings, row_order = self._candidate(cells, orders)
            signature = tuple(orders[0]) if orders else ()
            choice = (score, tuple(-col for col in signature))

            if best is None or choice > best[0]:
                best = (choice, strings, row_order, orders)

        _, strings, row_order, orders = best

        output = np.empty((n, m), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            permutation = orders[source]
            output[destination, :] = [
                raw[source, col] for col in permutation
            ]
            column_orders.append([
                df.columns[col] for col in permutation
            ])

        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders

